SINA_SMART["anat3-ocular-clinical"] = {"lecture":"anat3-ocular-clinical","title":"Vascular supply and applied anatomy of the eye","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"anat3-ocular-clinical:s0","text":"Describe and explain: The big picture","topic":"The big picture","sec":0,"importance":"standard","highYield":"untested"},{"id":"anat3-ocular-clinical:s1","text":"Describe and explain: What the lecture asks you to do","topic":"What the lecture asks you to do","sec":1,"importance":"standard","highYield":"untested"},{"id":"anat3-ocular-clinical:e0","text":"The ophthalmic artery is the first branch of the internal carotid and enters through the optic canal.","topic":"The ophthalmic artery","sec":2,"importance":"core","highYield":"untested"},{"id":"anat3-ocular-clinical:e1","text":"Orbital branches: internal palpebral, frontal, nasal, lacrimal, supraorbital, anterior and posterior ethmoidal.","topic":"The ophthalmic artery","sec":2,"importance":"core","highYield":"untested"},{"id":"anat3-ocular-clinical:e2","text":"Ocular branches: short ciliary (choroid, ciliary processes), long ciliary (anterior segment), central retinal (retina), muscular.","topic":"The ophthalmic artery","sec":2,"importance":"core","highYield":"untested"},{"id":"anat3-ocular-clinical:e3","text":"The central retinal artery enters the optic nerve sheath about 13 mm behind the globe.","topic":"The ophthalmic artery","sec":2,"importance":"core","highYield":"untested"},{"id":"anat3-ocular-clinical:e4","text":"Superior ophthalmic vein is the main drainage, through the superior orbital fissure to the cavernous sinus.","topic":"Venous drainage","sec":3,"importance":"core","highYield":"untested"},{"id":"anat3-ocular-clinical:e5","text":"Vortex veins drain the uveal tract and pierce the sclera behind the equator.","topic":"Venous drainage","sec":3,"importance":"core","highYield":"untested"},{"id":"anat3-ocular-clinical:e6","text":"Strabismus types: esotropia in, exotropia out, hypotropia down, hypertropia up.","topic":"Disorders of eye movement and refraction","sec":4,"importance":"core","highYield":"untested"},{"id":"anat3-ocular-clinical:e7","text":"Nystagmus: repetitive uncontrolled movements, horizontal, vertical or rotary, usually from brain injury.","topic":"Disorders of eye movement and refraction","sec":4,"importance":"core","highYield":"untested"},{"id":"anat3-ocular-clinical:e8","text":"Myopia: image in front of the retina. Hyperopia: image behind the retina.","topic":"Disorders of eye movement and refraction","sec":4,"importance":"core","highYield":"untested"},{"id":"anat3-ocular-clinical:e9","text":"Blowout fracture: the floor is most common; the medial wall second; the roof can leak CSF; the lateral wall is the strongest.","topic":"Orbital trauma","sec":5,"importance":"core","highYield":"untested"},{"id":"anat3-ocular-clinical:e10","text":"Ptosis: levator palpebrae superioris, CN III, plus the sympathetic superior tarsal muscle.","topic":"Conditions of the eye and lids","sec":6,"importance":"core","highYield":"untested"},{"id":"anat3-ocular-clinical:e11","text":"Chalazion: blocked meibomian gland inside the lid. Stye: blocked oil gland at the lid edge.","topic":"Conditions of the eye and lids","sec":6,"importance":"core","highYield":"untested"},{"id":"anat3-ocular-clinical:e12","text":"Conjunctivitis: outer layer. Uveitis: middle layer.","topic":"Conditions of the eye and lids","sec":6,"importance":"core","highYield":"untested"},{"id":"anat3-ocular-clinical:e13","text":"Papilloedema: optic disc swelling from raised intracranial pressure.","topic":"Conditions of the eye and lids","sec":6,"importance":"core","highYield":"untested"},{"id":"anat3-ocular-clinical:e14","text":"Glaucoma: damage to the optic nerve, open-angle slow, closed-angle sudden.","topic":"Conditions of the eye and lids","sec":6,"importance":"core","highYield":"untested"},{"id":"anat3-ocular-clinical:e15","text":"Direct reflex: same eye. Consensual reflex: opposite eye.","topic":"Clinical signs to reason through","sec":7,"importance":"core","highYield":"untested"},{"id":"anat3-ocular-clinical:e16","text":"Absent corneal reflex: deep coma or stroke, or a trigeminal or facial nerve lesion.","topic":"Clinical signs to reason through","sec":7,"importance":"core","highYield":"untested"},{"id":"anat3-ocular-clinical:e17","text":"Pituitary tumour at the chiasm: bitemporal hemianopia.","topic":"Clinical signs to reason through","sec":7,"importance":"core","highYield":"untested"},{"id":"anat3-ocular-clinical:e18","text":"Ganglion cells continue as the optic nerve.","topic":"Clinical signs to reason through","sec":7,"importance":"core","highYield":"untested"}],"vmap":{},"mlevel":{"1afgnpu":"a","26wg5y":"a","18k5ic3":"a","bheocu":"a","1eqhsej":"a","ndpp7c":"a","yrr330":"a","u9mfsu":"a","pe9c4":"a","y2ac1j":"a","gcwarj":"a","h5f0kw":"a","11k32gq":"a","16e0mpu":"a","19fe4lh":"a","f1cjqr":"a","1s6vxk5":"a","2vcxtf":"a","1tlvc1a":"a","1dsyurv":"a","yz9ynw":"a","1tk5ene":"a","svkp7w":"a","jo6gox":"a","5449uq":"a","1cq26cy":"a","1mwk1et":"a","jvn9r":"x"},"mapCounts":{"verified":0,"auto":27,"ambiguous":0,"missing":1},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"anat3-ocular-clinical:s0":{"s":0,"u":["First the vessels: one artery, the ophthalmic , supplies almost everything in the orbit, and the ophthalmic veins carry it all back to the cavernous sinus.","Second the clinic: what goes wrong, and why the anatomy explains it."],"dp":[]},"anat3-ocular-clinical:s1":{"s":1,"u":["Discuss the blood supply to the orbital region.","Briefly relate the clinical conditions associated with compromised vision to their anatomical reasoning."],"dp":[]},"anat3-ocular-clinical:e0":{"s":2,"u":["The ophthalmic artery is the first branch of the internal carotid and enters through the optic canal.","Blood supply to the orbit arises primarily from the ophthalmic artery , the first branch off the internal carotid as it emerges from the cavernous sinus on the medial side of the clinoid process.","It enters through the optic canal , runs along the medial wall of the orbit and divides into its terminal branches."],"dp":[{"h":"Note","t":"Ophthalmic artery = first branch of the internal carotid, enters via the optic canal . Its central retinal artery enters the optic nerve ~13 mm behind the globe and is an end artery ."}]},"anat3-ocular-clinical:e1":{"s":2,"u":["Orbital branches: internal palpebral, frontal, nasal, lacrimal, supraorbital, anterior and posterior ethmoidal.","Internal palpebral: Terminal branches, the superior and inferior medial palpebral arteries, supply the lacrimal sac and eyelids, creating an anastomosis with the two lateral palpebral branches from the lacrimal artery.","Anterior ethmoidal: In the orbit, the superior oblique muscle; also the anterior and middle ethmoidal cells, frontal sinus, lateral wall of the nose and nasal septum."],"dp":[]},"anat3-ocular-clinical:e2":{"s":2,"u":["Ocular branches: short ciliary (choroid, ciliary processes), long ciliary (anterior segment), central retinal (retina), muscular.","Short ciliary: The choroid and ciliary processes.","Long ciliary: The anterior segment; forms anastomoses with the extraocular muscle branches."],"dp":[]},"anat3-ocular-clinical:e3":{"s":2,"u":["The central retinal artery enters the optic nerve sheath about 13 mm behind the globe.","Central retinal: Branches off the posterior third of the ophthalmic artery and enters the dural sheath of the optic nerve about 13 mm behind the globe; supplies the retina."],"dp":[{"h":"Why central retinal artery occlusion blinds so fast","t":"The central retinal artery is an end artery: it enters the optic nerve sheath about 13 mm behind the globe and has almost no useful collateral supply to the inner retina. Block it and the inner retina loses its blood supply at once, giving sudden painless loss of vision in that eye. It is the eye's equivalent of a stroke, and it is treated with the same urgency. Source: the lecture's description of the central retinal artery and its course."},{"h":"Clinical","t":"Central retinal artery occlusion : sudden, painless loss of vision in one eye; pale retina with a cherry-red spot at the fovea."}]},"anat3-ocular-clinical:e4":{"s":3,"u":["Superior ophthalmic vein is the main drainage, through the superior orbital fissure to the cavernous sinus.","Superior ophthalmic vein: The main venous drainage of the orbit.","Originates in the superonasal quadrant and extends posteriorly through the medial part of the superior orbital fissure into the cavernous sinus."],"dp":[{"h":"Note","t":"Superior ophthalmic vein (main drainage) → superior orbital fissure → cavernous sinus . Vortex veins drain the choroid."},{"h":"Clinical","t":"Danger zone : facial infection → facial/angular vein → ophthalmic veins → cavernous sinus thrombosis (proptosis, ophthalmoplegia of III, IV, VI, V1 numbness)."}]},"anat3-ocular-clinical:e5":{"s":3,"u":["Vortex veins drain the uveal tract and pierce the sclera behind the equator.","Vortex veins: Venous drainage of the uveal tract; pierce the sclera posterior to the globe's equator and drain into the two main veins.","Inferior ophthalmic vein: Originates at the floor and medial wall of the orbit and drains the inferior orbit."],"dp":[]},"anat3-ocular-clinical:e6":{"s":4,"u":["Strabismus types: esotropia in, exotropia out, hypotropia down, hypertropia up.","Esotropia: Inward turning.","Exotropia: Outward turning."],"dp":[]},"anat3-ocular-clinical:e7":{"s":4,"u":["Nystagmus: repetitive uncontrolled movements, horizontal, vertical or rotary, usually from brain injury.","The movements can be horizontal, vertical or rotary.","It is caused by a miscommunication between the eye and the brain, affecting the way the brain interprets movement signals; it is typically caused by brain injuries and results from brain damage."],"dp":[]},"anat3-ocular-clinical:e8":{"s":4,"u":["Myopia: image in front of the retina. Hyperopia: image behind the retina.","Farsightedness (hyperopia) is the visual image being focused behind the retina rather than directly on it; it may be caused by the eyeball being too small or the focusing power being too weak."],"dp":[{"h":"Note","t":"Strabismus : eso = in, exo = out, hyper = up, hypo = down. Myopia : image in front of the retina (long eye) → concave lens. Hyperopia : image behind the retina (short eye) → convex lens."}]},"anat3-ocular-clinical:e9":{"s":5,"u":["Blowout fracture: the floor is most common; the medial wall second; the roof can leak CSF; the lateral wall is the strongest.","The most common are those of the inferior orbital wall, the floor .","Following inferior blowout fractures, the second commonest is that of the medial wall , with prolapse of the medial rectus muscle and orbital fat into the air cells of the ethmoid."],"dp":[{"h":"Why the floor of the orbit gives way first","t":"The lecture asks which wall is most prone to injury and which is strongest. The answer follows from the bones: the floor is thin maxillary bone sitting over the air-filled maxillary sinus, so a blow to the globe transmits pressure into the orbit and the floor buckles into the sinus below, taking fat and sometimes the inferior rectus with it. The lateral wall, of zygomatic bone and the greater wing of the sphenoid, is thick and buttressed by muscle, so it only fails in severe craniofacial trauma. Source: the lecture's blowout fracture slides, read with the orbital wall anatomy from the first lecture."},{"h":"Note","t":"Blowout fractures : floor most common (inferior rectus trapped), then medial wall (medial rectus into ethmoid cells); roof fractures can leak CSF ; the lateral wall rarely breaks."}]},"anat3-ocular-clinical:e10":{"s":6,"u":["Ptosis: levator palpebrae superioris, CN III, plus the sympathetic superior tarsal muscle.","The levator palpebrae superioris raises the lid and is supplied by CN III; its smooth superior tarsal part is sympathetic.","Ptosis: Drooping of the eyelid."],"dp":[]},"anat3-ocular-clinical:e11":{"s":6,"u":["Chalazion: blocked meibomian gland inside the lid. Stye: blocked oil gland at the lid edge.","Chalazion and stye: A chalazion is a blocked meibomian gland within the lid; a stye is a blocked oil gland on the edge of the eyelid."],"dp":[{"h":"Note","t":"Chalazion = blocked meibomian gland inside the lid (painless lump). Stye = infected gland at the lid margin (painful). Conjunctivitis = outer layer; uveitis = middle layer."}]},"anat3-ocular-clinical:e12":{"s":6,"u":["Conjunctivitis: outer layer. Uveitis: middle layer.","Conjunctivitis: Pink eye, affecting the outer layer.","Uveitis: Affects the middle layer; may be the result of inflammation associated with an autoimmune disorder."],"dp":[]},"anat3-ocular-clinical:e13":{"s":6,"u":["Papilloedema: optic disc swelling from raised intracranial pressure.","Papilloedema: Optic disc swelling secondary to raised intracranial pressure.","Eye pressure is a major risk factor."],"dp":[{"h":"Clinical","t":"Papilloedema = swollen optic disc from raised intracranial pressure (the optic nerve sheath continues the subarachnoid space). Retinal detachment : flashes, floaters, a curtain over vision: an emergency."}]},"anat3-ocular-clinical:e14":{"s":6,"u":["Glaucoma: damage to the optic nerve, open-angle slow, closed-angle sudden.","Closed-angle: often high and sudden.","Open-angle: the increase is often small and slow."],"dp":[{"h":"Clinical","t":"Glaucoma : open-angle = slow, painless, peripheral field loss first; closed-angle = sudden red painful eye, halos, fixed mid-dilated pupil: an emergency."}]},"anat3-ocular-clinical:e15":{"s":7,"u":["Direct reflex: same eye. Consensual reflex: opposite eye.","Direct and consensual pupillary light reflex.","A consensual reflex is the response of a pupil to light that enters the contralateral (opposite) eye."],"dp":[]},"anat3-ocular-clinical:e16":{"s":7,"u":["Absent corneal reflex: deep coma or stroke, or a trigeminal or facial nerve lesion.","Unilateral loss may also indicate a lesion involving the trigeminal or facial nerve.","Absence may indicate deep coma or stroke, either unilaterally or bilaterally."],"dp":[{"h":"Why a facial nerve palsy threatens the cornea","t":"The orbicularis oculi closes the lid, and it is supplied by CN VII. Lose that nerve and the eye cannot close fully, so the cornea dries out and loses the protective sweep of the blink. Because the corneal reflex's efferent limb is also CN VII, the reflex is lost on that side even though sensation through V1 is intact. That is why eye protection is part of managing a facial palsy. Source: the lecture's facial nerve palsy and corneal reflex slides."}]},"anat3-ocular-clinical:e17":{"s":7,"u":["Pituitary tumour at the chiasm: bitemporal hemianopia.","A pituitary tumour compressing the optic chiasma produces bitemporal hemianopia , because the crossing nasal fibres carry the temporal halves of both visual fields."],"dp":[{"h":"Note","t":"Pituitary tumour → bitemporal hemianopia (crossing nasal fibres carry the temporal fields). Not homonymous, not monocular."}]},"anat3-ocular-clinical:e18":{"s":7,"u":["Ganglion cells continue as the optic nerve.","Which cells continue as the optic nerve?","The ganglion cells : their axons leave the eye at the optic disc."],"dp":[]}},"meta":{"1afgnpu":{"a":"recall","vg":"anat3-ocular-clinical:e0/recall/1"},"26wg5y":{"a":"recall","vg":"anat3-ocular-clinical:e0/recall/2"},"18k5ic3":{"a":"recall","vg":"anat3-ocular-clinical:e1/recall/1"},"bheocu":{"a":"recall","vg":"anat3-ocular-clinical:e3/recall/1"},"1eqhsej":{"a":"recall","vg":"anat3-ocular-clinical:e2/recall/1"},"ndpp7c":{"a":"recall","vg":"anat3-ocular-clinical:e4/recall/1"},"yrr330":{"a":"recall","vg":"anat3-ocular-clinical:e5/recall/1"},"u9mfsu":{"a":"recall","vg":"anat3-ocular-clinical:e6/recall/1"},"pe9c4":{"a":"recall","vg":"anat3-ocular-clinical:e6/recall/2"},"y2ac1j":{"a":"recall","vg":"anat3-ocular-clinical:e7/recall/1"},"gcwarj":{"a":"recall","vg":"anat3-ocular-clinical:e8/recall/1"},"h5f0kw":{"a":"recall","vg":"anat3-ocular-clinical:e9/recall/1"},"11k32gq":{"a":"recall","vg":"anat3-ocular-clinical:e9/recall/2"},"16e0mpu":{"a":"application","vg":"anat3-ocular-clinical:e9/application/1"},"19fe4lh":{"a":"recall","vg":"anat3-ocular-clinical:e10/recall/1"},"f1cjqr":{"a":"recall","vg":"anat3-ocular-clinical:e16/recall/1"},"1s6vxk5":{"a":"relationship","vg":"anat3-ocular-clinical:e11/relationship/1"},"2vcxtf":{"a":"recall","vg":"anat3-ocular-clinical:e12/recall/1"},"1tlvc1a":{"a":"recall","vg":"anat3-ocular-clinical:e13/recall/1"},"1dsyurv":{"a":"recall","vg":"anat3-ocular-clinical:e18/recall/1"},"yz9ynw":{"a":"recall","vg":"anat3-ocular-clinical:e18/recall/2"},"1tk5ene":{"a":"recall","vg":"anat3-ocular-clinical:e17/recall/1"},"svkp7w":{"a":"recall","vg":"anat3-ocular-clinical:e16/recall/2"},"jo6gox":{"a":"recall","vg":"anat3-ocular-clinical:e3/recall/2"},"5449uq":{"a":"recall","vg":"anat3-ocular-clinical:e5/recall/2"},"1cq26cy":{"a":"recall","vg":"anat3-ocular-clinical:e9/recall/3"},"1mwk1et":{"a":"recall","vg":"anat3-ocular-clinical:e7/recall/1"}},"explRev":"4516ac7ff3f2"};
